  assign SimDTM_reset = reset;
  assign SimDTM_debug_req_ready = ldut_debug_clockeddmi_dmi_req_ready;
  assign SimDTM_debug_resp_valid = ldut_debug_clockeddmi_dmi_resp_valid;
